package com.retailflow.pos.purchaseorder;
import com.retailflow.pos.purchasebill.*;import jakarta.persistence.EntityNotFoundException;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PurchaseOrderService{
 private final PurchaseOrderRepository repo;private final PurchaseBillRepository bills;public PurchaseOrderService(PurchaseOrderRepository repo,PurchaseBillRepository bills){this.repo=repo;this.bills=bills;}
 public List<PurchaseOrder>list(PurchaseOrder.Status s){return s==null?repo.findAll():repo.findByStatus(s);}public PurchaseOrder get(String id){return repo.findById(id).orElseThrow(()->new EntityNotFoundException("Purchase order not found"));}public PurchaseOrder save(PurchaseOrder v){return repo.save(v);}
 @Transactional public PurchaseOrder transition(String id,PurchaseOrder.Status status){var v=get(id);v.setStatus(status);if(status==PurchaseOrder.Status.RECEIVED)v.setReceivedDate(LocalDate.now());return repo.save(v);}
 @Transactional public PurchaseBill createBill(String id){var po=get(id);var bill=PurchaseBill.builder().billNo("PB-"+System.currentTimeMillis()).supplier(po.getSupplier()).supplierName(po.getSupplierName()).supplierGstin(po.getSupplierGstin()).linkedPo(po).status(PurchaseBill.Status.DRAFT).subtotal(po.getSubtotal()).totalCgst(po.getTotalCgst()).totalSgst(po.getTotalSgst()).totalIgst(po.getTotalIgst()).totalGst(po.getTotalGst()).grandTotal(po.getGrandTotal()).amountPaid(BigDecimal.ZERO).balanceDue(po.getGrandTotal()).billDate(LocalDate.now()).items(po.getItems().stream().map(i->PurchaseBillItem.builder().productId(i.getProductId()).productName(i.getProductName()).sku(i.getSku()).quantity(i.getOrderedQty()).unitCost(i.getUnitCost()).gstRate(i.getGstRate()).cgst(i.getCgst()).sgst(i.getSgst()).igst(i.getIgst()).lineTotal(i.getLineTotal()).updateStock(true).build()).toList()).build();bill.getItems().forEach(i->i.setPurchaseBill(bill));return bills.save(bill);}
}
